--
-- `updated_at` triggers, for the properties declaring `autoValue: "on_update"`,
-- and the triggers that keep a row in its tenant.
-- Applied by Rebase, not by Atlas — a trigger is a function plus a binding,
-- and Atlas's free tier refuses to parse a desired state containing one.

CREATE OR REPLACE FUNCTION rebase.keep_tenant() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
    IF row_security_active(TG_RELID) THEN
        IF to_jsonb(OLD) -> TG_ARGV[0] IS DISTINCT FROM to_jsonb(NEW) -> TG_ARGV[0] THEN
            IF NOT (string_to_array(COALESCE(current_setting('app.user_roles', true), ''), ',') && TG_ARGV[1:TG_NARGS - 1]) THEN
                RAISE EXCEPTION 'TENANT_IMMUTABLE: an update cannot move a row of "%" to another tenant (column "%")', TG_TABLE_NAME, TG_ARGV[0]
                    USING ERRCODE = '42501',
                          HINT = 'Move it as a role listed in the collection''s tenant.bypassRoles.';
            END IF;
        END IF;
    END IF;
    RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS "projects_keep_tenant" ON "public"."projects";
CREATE TRIGGER "projects_keep_tenant" BEFORE UPDATE ON "public"."projects" FOR EACH ROW EXECUTE FUNCTION rebase.keep_tenant('org_id', 'admin');

DROP TRIGGER IF EXISTS "tasks_keep_tenant" ON "public"."tasks";
CREATE TRIGGER "tasks_keep_tenant" BEFORE UPDATE ON "public"."tasks" FOR EACH ROW EXECUTE FUNCTION rebase.keep_tenant('org_id', 'admin', 'support');

